def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp_count = 0
    rich_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_opp_count += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    my_urgent = hp <= 4 or no_water_days >= 1
    my_critical = hp <= 2 or no_water_days >= 2

    if my_critical:
        target = max(0.92 * DAILY_SALARY, highest_prev + 3.0, 64.0)
    elif my_urgent:
        target = max(0.72 * DAILY_SALARY, 0.45 * highest_prev + 18.0, 46.0 + 10.0 * scarcity)
    else:
        if supply >= 22:
            target = 12.0 + 6.0 * scarcity
        elif supply >= 19:
            target = 16.0 + 10.0 * scarcity
        else:
            target = 22.0 + 14.0 * scarcity

        if highest_prev > 150:
            target = min(target, 24.0 if hp > 5 else 40.0)
        elif highest_prev > 100:
            target = min(target + 3.0, 32.0 if hp > 5 else 45.0)
        else:
            target = max(target, min(highest_prev + 1.5, 38.0))

    if urgent_opp_count >= 2 and not my_urgent:
        target *= 0.88
    if rich_opp_count >= 2 and supply <= 17:
        target += 6.0
    if day >= 8 and hp >= 6 and not my_urgent:
        target *= 0.9

    if budget < DAILY_SALARY:
        target = min(target, 0.55 * budget)
    else:
        target = min(target, 0.85 * budget)

    target = max(0.0, min(target, budget))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] < 3:
        return min(my_status['budget'], avg_opp_bid * 1.2)

    if supply < WATER_REQ * 1.5:
        return min(my_status['budget'], avg_opp_bid * 1.05)

    return min(my_status['budget'], max(20.0, avg_opp_bid * 0.8))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 1.0)
        return min(budget, DAILY_SALARY * 0.2)

    # Look at yesterday's highest bid among alive opponents
    highest_prev_bid = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > highest_prev_bid:
                highest_prev_bid = prev['bid']

    # Estimate competitors' max budget and aggression
    # Basic threshold: if yesterday's max bid was very low, they might be conserving
    # If high, they are aggressive

    if hp <= 2:
        # Critical: must win water
        target = max(DAILY_SALARY * 1.5, highest_prev_bid * 1.1)
        return min(budget, target)

    if no_water_days >= 1:
        # Moderate desperation
        target = max(DAILY_SALARY * 1.2, highest_prev_bid * 0.9)
        return min(budget, target)

    # Healthy: conserve budget
    if highest_prev_bid > DAILY_SALARY * 0.8:
        # Opponents are aggressive, avoid price war if possible
        return min(budget, DAILY_SALARY * 0.4)
    else:
        # Opponents moderate, bid just enough to beat their history if needed
        base = max(DAILY_SALARY * 0.3, highest_prev_bid * 1.05)
        return min(budget, base)
